import{_ as e}from"./chunks/dds.iuNsdFVR.js";import{c as a,$ as o,Q as l,j as n,g as s,o as i,n as d,m as g}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Движение денег (ДДС)","description":"Учет кассы, наличные и безналичные потоки, смешанные финансы, личные инвестиции и проведение расходов в ОмниКрафт ЕРП.","frontmatter":{"title":"Движение денег (ДДС)","description":"Учет кассы, наличные и безналичные потоки, смешанные финансы, личные инвестиции и проведение расходов в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-14","order":3},"headers":[],"relativePath":"ru/docs/resources/dds.md","filePath":"ru/docs/resources/dds.md","lastUpdated":1794614400000}'),p={name:"ru/docs/resources/dds.md"},c={id:"движение-денег-ддс",tabindex:"-1"};function h(u,t,m,f,b,x){const r=o("DocIcon");return l(),n("div",null,[s("h1",c,[i(r,{name:"dds"}),t[0]||(t[0]=d(" Движение денег (ДДС) ",-1)),t[1]||(t[1]=s("a",{class:"header-anchor",href:"#движение-денег-ддс","aria-label":'Permalink to "Движение денег (ДДС)"'},"​",-1))]),t[2]||(t[2]=g('<figure class="doc-image craft-window-frame" data-title="Движение денег (ДДС) — ОмниКрафт ЕРП"><img src="'+e+'" alt="Главное окно вкладки «ДДС» (Движение денег)"><figcaption>Главное окно вкладки «ДДС» (Движение денег)</figcaption></figure><p>Вкладка <strong>«ДДС»</strong> (Движение денежных средств) служит единым расчетно-кассовым центром вашего дела. Вне зависимости от направления — создаёте ли вы вещи в цехе, ремонтируете технику в сервисном центре, продаёте товары на маркетплейсах или работаете как частный мастер — этот инструмент контролирует физическое наличие денег в кассе и на расчетных счетах.</p><p>В отличие от отчета «Капитал», где отражается общая совокупная стоимость всего бизнеса (включая станки, инструмент, складские остатки сырья и готовую продукцию), модуль ДДС работает по строгому кассовому методу. Он фиксирует каждую копейку исключительно в момент ее фактического поступления или списания, надежно защищая от кассовых разрывов.</p><hr><h2 id="физика-кассы-три-ключевых-индикатора" tabindex="-1">Физика кассы: Три ключевых индикатора <a class="header-anchor" href="#физика-кассы-три-ключевых-индикатора" aria-label="Permalink to &quot;Физика кассы: Три ключевых индикатора&quot;">​</a></h2><p>В верхней панели экрана расположены три главных финансовых счетчика, отражающих состояние кассы прямо сейчас:</p><ol><li><strong>Реальный приход (Касса):</strong> Сумма всех денежных средств, которые физически поступили в ваше дело (выручка от розничных продаж, авансы и расчеты по заказ-нарядам, плата за диагностику, доходы от мастер-классов).</li><li><strong>Реальный расход (Траты):</strong> Все фактически выплаченные деньги (закупка материалов и запчастей, оплата доставки, аренда помещений, реклама, сервисы, налоги).</li><li><strong>Свободный остаток (Сальдо):</strong> Разница между суммарным приходом и расходом на текущую секунду.</li></ol><hr><h2 id="философия-смешанных-финансов-почему-отрицательное-сальдо-—-норма" tabindex="-1">Философия смешанных финансов: Почему отрицательное сальдо — норма <a class="header-anchor" href="#философия-смешанных-финансов-почему-отрицательное-сальдо-—-норма" aria-label="Permalink to &quot;Философия смешанных финансов: Почему отрицательное сальдо — норма&quot;">​</a></h2><p>В классическом корпоративном бухучете отрицательный баланс кассы считается грубейшей ошибкой. В реальной жизни малого бизнеса, мастерских и частных специалистов ситуация иная: на старте или при расширении создатель оплачивает закупку станков, аренду и материалы со своей личной банковской карты или наличными из кармана.</p><p>Если заставлять человека оформлять на каждую покупку сложные юридические договоры займа учредителя, учет быстро превращается в бюрократический ад и забрасывается.</p><p>В <strong>ОмниКрафт ЕРП</strong> действует естественный закон <strong>смешанных финансов</strong>:</p><div class="tip custom-block"><p class="custom-block-title">Отрицательное сальдо — честный индикатор личных инвестиций</p><p>Отрицательное сальдо ДДС означает, что вы инвестировали в запуск или развитие дела личные сбережения. Программа честно фиксирует этот объем вложений со знаком минус.</p><p>Это наглядный ответ на вопрос: <em>«Сколько денег бизнес должен вернуть лично вам прямо сейчас?»</em></p></div><p>Как только сальдо кассы пересекает нулевую отметку и переходит в плюс, это означает, что проект полностью окупил стартовые вложения создателя и начал приносить чистый денежный доход.</p><hr><h2 id="практическии-пример-путь-от-личных-вложении-к-чистои-прибыли" tabindex="-1">Практический пример: Путь от личных вложений к чистой прибыли <a class="header-anchor" href="#практическии-пример-путь-от-личных-вложении-к-чистои-прибыли" aria-label="Permalink to &quot;Практический пример: Путь от личных вложений к чистой прибыли&quot;">​</a></h2><p>Чтобы наглядно увидеть, как отрицательное сальдо ДДС трансформируется в реальную прибыль, разберем типовой жизненный цикл проекта:</p><div class="quickstart-steps-grid"><div class="step-card"><div class="step-header"><span class="step-num-badge">01</span><h3 class="step-title">Стартовые вложения</h3></div><p class="step-desc"> Вы вложили личные накопления: приобрели станки и приборы на <strong>150 000 ₽</strong>, материалы на <strong>50 000 ₽</strong> и запустили рекламу на <strong>10 000 ₽</strong>.<br> • <strong>Сальдо ДДС:</strong> <span style="color:var(--vp-c-danger);font-weight:600;">-210 000 ₽</span> (размер личных вложений в дело).<br> • <strong>Баланс в Капитале:</strong> 200 000 ₽ (активы в виде техники и материалов). </p></div><div class="step-card"><div class="step-header"><span class="step-num-badge">02</span><h3 class="step-title">Работа и возврат вложений</h3></div><p class="step-desc"> Вы выполнили серию заказов: списали материалы на <strong>20 000 ₽</strong>, износ техники составил <strong>2 000 ₽</strong>, а клиенты оплатили <strong>80 000 ₽</strong>.<br> • <strong>Сальдо ДДС:</strong> -210 000 + 80 000 = <span style="color:var(--vp-c-danger);font-weight:600;">-130 000 ₽</span> (касса возвращает вложенное).<br> • <strong>Баланс в Капитале:</strong> 178 000 ₽ (станки 148 000 ₽ + сырье 30 000 ₽). </p></div><div class="step-card"><div class="step-header"><span class="step-num-badge">03</span><h3 class="step-title">Окупаемость и чистая прибыль</h3></div><p class="step-desc"> Вы переработали оставшиеся запасы (на <strong>30 000 ₽</strong>) и реализовали заказов еще на <strong>150 000 ₽</strong>.<br> • <strong>Сальдо ДДС:</strong> -130 000 + 150 000 = <span style="color:var(--vp-c-success);font-weight:600;">+20 000 ₽</span> (все 210 000 ₽ возвращены, касса вышла в плюс).<br> • <strong>Баланс в Капитале:</strong> 145 000 ₽ (оборудование сохраняет ценность и продолжает работать). </p></div></div><hr><h2 id="специфика-движения-денег-по-направлениям" tabindex="-1">Специфика движения денег по направлениям <a class="header-anchor" href="#специфика-движения-денег-по-направлениям" aria-label="Permalink to &quot;Специфика движения денег по направлениям&quot;">​</a></h2><p>Характер кассовых потоков различается в зависимости от того, чем именно занимается ваше предприятие:</p><h3 id="services" tabindex="-1">В сфере услуг <a class="header-anchor" href="#services" aria-label="Permalink to &quot;В сфере услуг {#services}&quot;">​</a></h3><p>В сервисных центрах, ремонтных мастерских, ателье и студиях ключевую роль играют предоплаты и разделение стоимости работы и запчастей:</p><ul><li><strong>Авансы по заказам:</strong> при приеме изделия в ремонт предоплата клиента сразу фиксируется в кассе, защищая от неоплаты закупленных под заказ деталей.</li><li><strong>Расход на комплектующие:</strong> детали, закупаемые под конкретный заказ-наряд, списываются в кассе в момент проведения закупки.</li><li><strong>Окончательный расчет:</strong> при выдаче готового заказа клиенту в кассу поступает доплата за работу мастера и расходники по акту выполненных работ.</li></ul><h3 id="production" tabindex="-1">В производстве <a class="header-anchor" href="#production" aria-label="Permalink to &quot;В производстве {#production}&quot;">​</a></h3><p>В ремесленном или серийном цехе касса обслуживает материально-производственный цикл:</p><ul><li><strong>Крупные партии сырья:</strong> касса финансирует оптовые закупки листового металла, кожи, древесины или полимеров.</li><li><strong>Транспортная логистика:</strong> расходы на доставку грузов списываются отдельным ордером, увеличивая учетную стоимость материалов на складе.</li><li><strong>Цеховые издержки:</strong> постоянные ежемесячные траты (аренда помещения, силовое электричество, отопление, отопительные печи) разносятся по соответствующим статьям.</li></ul><h3 id="trade" tabindex="-1">В торговле и у селлеров маркетплейсов <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;В торговле и у селлеров маркетплейсов {#trade}&quot;">​</a></h3><p>В интернет-магазинах и рознице касса привязана к графикам выплат торговых площадок:</p><ul><li><strong>Выплаты торговых площадок:</strong> выручка заходит не по каждому чеку отдельно, а периодическими траншами по отчетам реализации за вычетом комиссии платформы.</li><li><strong>Затраты на хранение и логистику:</strong> сопутствующие услуги складов и курьерских служб вносятся как прямые операционные расходы.</li><li><strong>Возвраты покупателей:</strong> при возврате товара покупателю оформляется расходная операция с привязкой к чеку.</li></ul><h3 id="masters" tabindex="-1">У частных специалистов <a class="header-anchor" href="#masters" aria-label="Permalink to &quot;У частных специалистов {#masters}&quot;">​</a></h3><p>Для индивидуальных мастеров ОмниКрафт ЕРП снимает необходимость открывать отдельный расчетный счет на самых ранних этапах. Вы просто ведете раздельный учет личных денег и кассы любимого дела в едином интерфейсе.</p><hr><h2 id="источники-денежных-потоков-автоматические-и-ручные" tabindex="-1">Источники денежных потоков: Автоматические и Ручные <a class="header-anchor" href="#источники-денежных-потоков-автоматические-и-ручные" aria-label="Permalink to &quot;Источники денежных потоков: Автоматические и Ручные&quot;">​</a></h2><p>Финансовый контур программы избавляет вас от двойного ввода данных. Большинство кассовых записей создаются системой автономно:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Источник операции</th><th style="text-align:left;">Направление</th><th style="text-align:left;">Как формируется запись</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Склад (Партионная закупка)</strong></td><td style="text-align:left;">Расход</td><td style="text-align:left;">Программа автоматически создает два ордера: стоимость сырья и стоимость доставки</td></tr><tr><td style="text-align:left;"><strong>Продажи (Кассовый чек)</strong></td><td style="text-align:left;">Приход</td><td style="text-align:left;">Выручка мгновенно поступает в кассу при пробитии продажи</td></tr><tr><td style="text-align:left;"><strong>Заказ-наряды (Сфера услуг)</strong></td><td style="text-align:left;">Приход</td><td style="text-align:left;">Оплата аванса и закрытие наряда увеличивают кассовый остаток</td></tr><tr><td style="text-align:left;"><strong>Мастерская (Покупка активов)</strong></td><td style="text-align:left;">Расход</td><td style="text-align:left;">Если оборудование оплачено из кассы, формируется расходный ордер</td></tr><tr><td style="text-align:left;"><strong>Онлайн-витрина</strong></td><td style="text-align:left;">Приход</td><td style="text-align:left;">Подтверждение интернет-заказа клиентом добавляет сумму в журнал</td></tr></tbody></table><h3 id="внесение-прочих-ручных-операции" tabindex="-1">Внесение прочих (ручных) операций <a class="header-anchor" href="#внесение-прочих-ручных-операции" aria-label="Permalink to &quot;Внесение прочих (ручных) операций&quot;">​</a></h3><p>Все сопутствующие движения денег, не связанные напрямую с типовыми продажами готовой продукции, вносятся через форму <strong>«Внести прочие операции»</strong> в правой части экрана:</p><ol><li><strong>Тип операции:</strong><ul><li><strong>Расход (Траты):</strong> эксплуатационные издержки дела (аренда, сервисы, реклама).</li><li><strong>Внереализационный доход:</strong> любые дополнительные поступления (проведение обучающего мастер-класса, платная консультация, сдача в аренду инструмента, реализация производственных отходов или обрезков).</li></ul></li><li><strong>Выбор статьи учета:</strong><ul><li><em>Для расходов:</em> <strong>Реклама</strong>, <strong>Хостинг и Сервисы</strong>, <strong>Аренда помещения</strong>, <strong>Транспорт</strong>, <strong>Обслуживание оборудования</strong> или универсальная категория <strong>Прочее</strong>.</li><li><em>Для доходов:</em> <strong>Мастер-класс</strong>, <strong>Индивидуальные услуги</strong>, <strong>Прочее</strong>.</li></ul></li><li><strong>Умный ввод суммы:</strong> при щелчке в поле ввода лишние нули автоматически стираются, ускоряя заполнение бланка.</li><li><strong>Выбор даты:</strong> вы можете провести операцию любым прошедшим числом через встроенный календарь.</li></ol><hr><h2 id="специальныи-блок-уплата-налога" tabindex="-1">Специальный блок: Уплата налога <a class="header-anchor" href="#специальныи-блок-уплата-налога" aria-label="Permalink to &quot;Специальный блок: Уплата налога&quot;">​</a></h2><p>Для предотвращения путаницы между производственными затратами и фискальными обязательствами в нижней части панели вынесена быстрая форма <strong>«Уплата налога»</strong>:</p><ol><li>Укажите сумму налога, рассчитанную по вашей системе налогообложения.</li><li>Выберите дату фактического списания средств.</li><li>Программа создаст ордер с защищенной системной статьей <strong>«Налоги»</strong>.</li></ol><p>Такие платежи изолируются в аналитических отчетах, позволяя видеть чистую операционную прибыль до налогообложения и после уплаты сборов.</p><hr><h2 id="журнал-кассы-и-финансовая-гигиена" tabindex="-1">Журнал кассы и финансовая гигиена <a class="header-anchor" href="#журнал-кассы-и-финансовая-гигиена" aria-label="Permalink to &quot;Журнал кассы и финансовая гигиена&quot;">​</a></h2><p>В левой части экрана находится хронологический реестр всех операций:</p><ul><li><strong>Цветовые акценты:</strong> поступления выделены зеленым цветом со знаком <strong>«+»</strong>, списания — красным со знаком <strong>«-»</strong>.</li><li><strong>Пагинация:</strong> журнал выводит записи блоками по 20 строк, гарантируя плавность интерфейса даже при тысячах операций за год.</li><li><strong>Запись прошлым числом:</strong> при оформлении задним числом программа присваивает операции нейтральное время <code>12:00:00</code>. Это исключает конфликты хронологии и сохраняет корректную последовательность сальдо на начало и конец каждого дня.</li></ul><h3 id="золотое-правило-создателя-не-путаите-выручку-с-личным-доходом" tabindex="-1">Золотое правило создателя: Не путайте выручку с личным доходом <a class="header-anchor" href="#золотое-правило-создателя-не-путаите-выручку-с-личным-доходом" aria-label="Permalink to &quot;Золотое правило создателя: Не путайте выручку с личным доходом&quot;">​</a></h3><p>Одна из главных причин закрытия небольших мастерских — привычка владельца забирать из кассы все поступившие деньги на личные нужды сразу после крупной сделки.</p><div class="warning custom-block"><p class="custom-block-title">Выручка в кассе — это не ваша чистая зарплата</p><p>Пока из полученной суммы не оплачены материалы на следующий заказ, аренда и налоги, эти деньги принадлежат делу.</p><p>Изымайте средства на личное потребление только через отдельный расходный ордер с комментарием <em>«Вывод прибыли»</em> или <em>«Личный доход владельца»</em>, сохраняя неснижаемый кассовый буфер на счетах.</p></div>',51))])}const _=a(p,[["render",h]]);export{y as __pageData,_ as default};
